import { readFile } from "node:fs/promises";
import { pathToFileURL } from "node:url";
import { DuckDBInstance } from "@duckdb/node-api";
import type { Page } from "@playwright/test";
import { expect, test } from "./fixtures";

// Loading the engine means fetching and compiling ~35 MB of WebAssembly.
const ENGINE_TIMEOUT = 60_000;
// A million rows arrive in about 490 batches (P-05); see results.spec.ts.
const MILLION_ROWS_TIMEOUT = 30_000;
// Samples are generated by the engine when they're loaded.
const SAMPLE_TIMEOUT = 30_000;
const LONG_WORK_MS = 50;

const results = (page: Page) => page.getByRole("grid", { name: "Results" });

async function runSql(page: Page, sql: string, rowCount: number) {
  await page.goto("/app/");
  await expect(page.getByRole("status")).toHaveText(/^Engine ready/, { timeout: ENGINE_TIMEOUT });
  await page.getByRole("textbox", { name: "SQL editor" }).click();
  await page.keyboard.type(sql);
  await page.keyboard.press("ControlOrMeta+Enter");
  await expect(results(page)).toHaveAttribute("aria-rowcount", String(rowCount + 1), {
    timeout: MILLION_ROWS_TIMEOUT,
  });
}

/** Clicks `button` and resolves with the download it starts. */
async function download(page: Page, button: string) {
  const started = page.waitForEvent("download");
  await page.getByRole("button", { name: button }).click();
  return started;
}

test.describe("Export", () => {
  test("exports the result as CSV", async ({ page }) => {
    await runSql(page, "SELECT range AS n, 'row ' || range AS label FROM range(3);", 3);

    const file = await download(page, "Export as CSV");

    expect(file.suggestedFilename()).toMatch(/^blinkql-result-[\d-]+\.csv$/);
    expect(await readFile(await file.path(), "utf8")).toBe("n,label\n0,row 0\n1,row 1\n2,row 2\n");
    await expect(page.getByText(`Downloaded ${file.suggestedFilename()}`)).toBeVisible();
  });

  test("exports the result as Parquet", async ({ page }) => {
    await runSql(page, "SELECT range AS n, range * 1.5 AS amount FROM range(100)", 100);

    const file = await download(page, "Export as Parquet");

    expect(file.suggestedFilename()).toMatch(/^blinkql-result-[\d-]+\.parquet$/);
    const path = (await file.path()).replaceAll("\\", "/");
    const instance = await DuckDBInstance.create(":memory:");
    const connection = await instance.connect();
    const reader = await connection.runAndReadAll(
      `SELECT count(*)::INTEGER AS rows, sum(amount)::DOUBLE AS total FROM read_parquet('${path}')`,
    );
    connection.closeSync();
    instance.closeSync();
    expect(reader.getRowObjects()).toEqual([{ rows: 100, total: 7425 }]);
  });

  test("says why a result can't be exported", async ({ page }) => {
    await runSql(page, "CREATE TABLE t AS SELECT 1 AS a", 1);

    await page.getByRole("button", { name: "Export as CSV" }).click();

    await expect(page.getByText(/^Couldn't export: /)).toBeVisible();
  });

  test("exports a million-row result without blocking the main thread", async ({
    page,
    longWorkDuringQueries,
  }) => {
    test.setTimeout(120_000);
    await runSql(page, "SELECT range AS n, random() AS v FROM range(1000000)", 1_000_000);
    expect(await longWorkDuringQueries()).toEqual([]);

    const exportStart = await page.evaluate(() => performance.now());
    const file = await download(page, "Export as CSV");
    await expect(page.getByText(`Downloaded ${file.suggestedFilename()}`)).toBeVisible({
      timeout: MILLION_ROWS_TIMEOUT,
    });
    const longWork = await page.evaluate(
      async ({ since, budget }) => {
        // Long animation frames are reported only after they end.
        await new Promise((resolve) => requestAnimationFrame(() => setTimeout(resolve)));
        return (window.blinkqlLongWork ?? []).filter(
          (work) => work.duration > budget && work.startTime + work.duration > since,
        );
      },
      { since: exportStart, budget: LONG_WORK_MS },
    );

    expect(longWork).toEqual([]);
    const lines = (await readFile(await file.path(), "utf8")).trimEnd().split("\n");
    expect(lines).toHaveLength(1_000_001);
    expect(lines[0]).toBe("n,v");
  });

  test("exports a chart as a PNG", async ({ page }) => {
    await runSql(page, "SELECT range % 3 AS k FROM range(30)", 30);
    await page.getByRole("button", { name: "Chart", exact: true }).click();
    await expect(page.getByRole("img", { name: "Bar chart of count(*) by k" })).toBeVisible();

    const file = await download(page, "Export PNG");

    expect(file.suggestedFilename()).toMatch(/^blinkql-chart-[\d-]+\.png$/);
    const png = await readFile(await file.path());
    expect([...png.subarray(0, 8)]).toEqual([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  });

  test("exports the query, chart and result as an HTML report that works offline", async ({
    page,
    makeAxeBuilder,
  }) => {
    test.setTimeout(120_000);
    await page.goto("/app/");
    await expect(page.getByRole("status")).toHaveText(/^Engine ready/, { timeout: ENGINE_TIMEOUT });
    await page.getByRole("button", { name: "Load sample data" }).click();
    const samples = page.getByRole("dialog", { name: "Load sample data" });
    await samples.getByRole("button", { name: /^Quality checks/ }).click();
    await expect(samples).toBeHidden({ timeout: SAMPLE_TIMEOUT });
    // Few rows, as an axe scan of a long table takes minutes; the row limit has unit tests.
    const sql = "SELECT * FROM quality_checks ORDER BY check_id LIMIT 40";
    await page.getByRole("textbox", { name: "SQL editor" }).click();
    await page.keyboard.type(sql);
    await page.keyboard.press("ControlOrMeta+Enter");
    const grid = results(page);
    await expect(grid).toHaveAttribute("aria-rowcount", "41", { timeout: SAMPLE_TIMEOUT });
    const headers = await grid.getByRole("columnheader").allTextContents();
    const firstRow = await grid.getByRole("row").nth(1).getByRole("gridcell").allTextContents();
    await page.getByRole("button", { name: "Chart", exact: true }).click();
    const chart = page.getByRole("img", {
      name: /^Bar chart of count\(\*\) by machine_id, 8 bars/,
    });
    await expect(chart).toBeVisible();
    const chartLabel = await chart.getAttribute("aria-label");

    const file = await download(page, "Export as HTML report");

    expect(file.suggestedFilename()).toMatch(/^blinkql-report-[\d-]+\.html$/);
    await expect(page.getByText(`Downloaded ${file.suggestedFilename()}`)).toBeVisible();
    const html = await readFile(await file.path(), "utf8");
    expect(html).toMatch(/^<!doctype html>/);

    // Opened with no network: it must not ask for anything.
    const requests: string[] = [];
    page.on("request", (request) => {
      if (/^https?:/.test(request.url())) requests.push(request.url());
    });
    // Opened as a file, as it would be from the downloads folder, so only the report's own Content
    // Security Policy applies. A blank page would inherit the app's in WebKit.
    const saved = test.info().outputPath("report.html");
    await file.saveAs(saved);
    await page.context().setOffline(true);
    await page.goto(pathToFileURL(saved).href);

    // Its policy allows its inline styles.
    await expect(page.locator("body")).toHaveCSS("max-width", "1152px");
    await expect(page.locator("pre code")).toHaveText(sql);
    await expect(page.getByRole("img", { name: chartLabel ?? "" })).toBeVisible();
    expect(
      await page.getByRole("img").evaluate((image: HTMLImageElement) => image.naturalWidth),
    ).toBeGreaterThan(0);
    const table = page.getByRole("table", { name: "Result: 40 rows" });
    await expect(table.getByRole("columnheader")).toHaveText(headers);
    await expect(table.getByRole("row")).toHaveCount(41);
    await expect(table.getByRole("row").nth(1).getByRole("cell")).toHaveText(firstRow);
    expect(requests).toEqual([]);

    for (const colorScheme of ["light", "dark"] as const) {
      await page.emulateMedia({ colorScheme });
      const scan = await makeAxeBuilder().analyze();
      expect(scan.violations, `axe violations in ${colorScheme} mode`).toEqual([]);
    }
  });

  test("pictures the chart in a report on the report's own background, whatever the app's theme", async ({
    page,
  }) => {
    // The app in dark mode, as chosen on the landing page.
    await page.addInitScript(() => localStorage.setItem("blinkql-theme", "dark"));
    await runSql(page, "SELECT range % 3 AS k FROM range(30)", 30);
    await page.getByRole("button", { name: "Chart", exact: true }).click();
    await expect(page.getByRole("img", { name: "Bar chart of count(*) by k" })).toBeVisible();
    const file = await download(page, "Export as HTML report");
    const saved = test.info().outputPath("report.html");
    await file.saveAs(saved);
    await page.goto(pathToFileURL(saved).href);

    for (const [media, colorScheme] of [
      ["screen", "light"],
      ["screen", "dark"],
      ["print", "dark"],
    ] as const) {
      await page.emulateMedia({ media, colorScheme });
      await expect(page.getByRole("img")).toHaveCount(1);
      const { chart, background } = await page.getByRole("img").evaluate(chartCorner);
      expect(chart, `the chart's background on ${media} in ${colorScheme} mode`).toEqual(
        background,
      );
    }
  });
});

/** The top-left pixel of `image` and the page's background, as [r, g, b]. */
async function chartCorner(image: HTMLImageElement) {
  await image.decode();
  const context = document
    .createElement("canvas")
    .getContext("2d", { willReadFrequently: true }) as CanvasRenderingContext2D;
  const rgb = () => [...context.getImageData(0, 0, 1, 1).data.subarray(0, 3)];
  context.drawImage(image, 0, 0, 1, 1, 0, 0, 1, 1);
  const chart = rgb();
  context.fillStyle = getComputedStyle(document.body).backgroundColor;
  context.fillRect(0, 0, 1, 1);
  return { chart, background: rgb() };
}
